const A = '0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ';
function encode(n) {
  if (n === 0) return '0';
  let s = '';
  while (n > 0) { s = A[n % 62] + s; n = Math.floor(n / 62); }
  return s;
}
function decode(s) {
  let n = 0;
  for (const ch of s) n = n * 62 + A.indexOf(ch);
  return n;
}
```
`3843 = 61·62 + 61` → **"ZZ"** (the largest 2-character code).
